<?php include 'config.php'; if(!isLoggedIn()){header('Location: login.php');exit;} $uid=$_SESSION['user_id']; $user=$conn->query("SELECT * FROM users WHERE user_id=$uid")->fetch_assoc(); $items=$conn->query("SELECT ci.*,p.price FROM cart_items ci JOIN products p ON ci.product_id=p.product_id WHERE ci.user_id=$uid"); $arr=[];$total=0; while($x=$items->fetch_assoc()){$arr[]=$x;$total+=$x['price']*$x['quantity'];} if($_SERVER['REQUEST_METHOD']==='POST'){ $ad=$conn->real_escape_string($_POST['address']); $conn->query("INSERT INTO orders(user_id,total_amount,shipping_address) VALUES($uid,$total,'$ad')"); $oid=$conn->insert_id; foreach($arr as $it){$conn->query("INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES($oid,{$it['product_id']},{$it['quantity']},{$it['price']})");} $conn->query("DELETE FROM cart_items WHERE user_id=$uid"); header('Location: profile.php');exit;} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Checkout</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'nav.php'; ?><form class="form" method="POST"><h1>Checkout</h1><p>Total: $<?=number_format($total,2)?></p><label>Address</label><textarea name="address"><?=clean($user['address'])?></textarea><button>Place Order</button></form></body></html>